import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import test from "node:test";

import { g7Preview } from "../src/analysis-engine.js";
import { calculateCompensation, parseImportText } from "../src/curve-engine.js";
import { buildPatchMap, standardById } from "../src/standards.js";

// Fully synthetic G7-style sheet generated by scripts/generate-demo-g7.mjs (no third-party data).
const fixture = "samples/g7-demo-synthetic.txt";

test("synthetic G7 demo sheet parses into CTV-capable measurements", async () => {
  const parsed = await parseFixture(fixture);
  const results = calculateCompensation(parsed.measurements, { mode: "ctv", target: "linear", compensationRatio: 50, smooth: 0, limit: 18 });

  assert.equal(parsed.sourceFormat, "CGATS/IT8");
  assert.equal(parsed.rawRows.length, 69);
  assert.ok(parsed.measurements.length >= 48);
  assert.ok(results.length > 0);
  assert.ok(parsed.measurements.every((row) => Number.isFinite(row.colorimetricTone)));
});

test("synthetic G7 demo sheet gives a complete G7 check with TR015 aims", async () => {
  const parsed = await parseFixture(fixture);
  const preview = g7Preview({
    measurements: parsed.measurements,
    results: calculateCompensation(parsed.measurements, { mode: "ctv", target: "linear", compensationRatio: 50, smooth: 0, limit: 18 }),
    rawRows: parsed.rawRows,
    metadata: parsed.metadata,
    standardPatchMap: buildPatchMap(standardById("gracol2013_crpc6").referenceRows),
    deltaEFormula: "de76",
  });

  assert.equal(preview.missing.length, 0, preview.missing.join(" / "));
  assert.equal(preview.kOnlyCount, 12);
  assert.equal(preview.grayPatchCount, 12);
  assert.ok(["Pass", "Fail"].includes(preview.status));
  assert.equal(preview.npdcVerification.find((row) => row.tone === 50)?.targetSource, "tr015_measured_solid");
  assert.ok(preview.colorspaceRows.some((row) => Number.isFinite(row.deltaE)));
});

async function parseFixture(file) {
  return parseImportText(await readFile(path.resolve(file), "utf8"));
}
